selector_to_html = {"a[href=\"SectionProfiles.html#pyskyfire.regen.cross_section.SectionProfiles\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.regen.cross_section.SectionProfiles\">\n<span class=\"property\"><span class=\"k\"><span class=\"pre\">class</span></span><span class=\"w\"> </span></span><span class=\"sig-prename descclassname\"><span class=\"pre\">pyskyfire.regen.cross_section.</span></span><span class=\"sig-name descname\"><span class=\"pre\">SectionProfiles</span></span></dt><dd><p>All geometry profiles along the cooling-channel centerline.</p><p>Each required array must have consistent length <code class=\"docutils literal notranslate\"><span class=\"pre\">N</span></code> (number of stations).</p></dd>", "a[href=\"ChannelSection.html#pyskyfire.regen.cross_section.ChannelSection\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.regen.cross_section.ChannelSection\">\n<span class=\"property\"><span class=\"k\"><span class=\"pre\">class</span></span><span class=\"w\"> </span></span><span class=\"sig-prename descclassname\"><span class=\"pre\">pyskyfire.regen.cross_section.</span></span><span class=\"sig-name descname\"><span class=\"pre\">ChannelSection</span></span><span class=\"sig-paren\">(</span><em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">n_points</span></span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"default_value\"><span class=\"pre\">16</span></span></em>, <em class=\"sig-param\"><span class=\"keyword-only-separator o\"><abbr title=\"Keyword-only parameters separator (PEP 3102)\"><span class=\"pre\">*</span></abbr></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">exposure</span></span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"default_value\"><span class=\"pre\">None</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">exposure_angles</span></span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"default_value\"><span class=\"pre\">None</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">enable_fin</span></span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"default_value\"><span class=\"pre\">False</span></span></em><span class=\"sig-paren\">)</span></dt><dd><p>A section with floor, roof, and two sidewalls.</p><p>exposure maps surface names to centred fractions in [0, 1], optionally\ndesign-input callables. Unspecified surfaces are inactive; the default is\nthe complete floor. exposure_angles selects rounded-lobe spans in radians\ninstead. A surface cannot specify both forms.</p><p>enable_fin applies one symmetric rib model to both sidewalls, incompatible\nwith direct sidewall exposure. CoolingCircuit supplies its own fin switch;\nindependent sections use this switch. All surfaces count toward Dh.</p></dd>", "a[href=\"#module-pyskyfire.regen.cross_section\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">pyskyfire.regen.cross_section<a class=\"headerlink\" href=\"#module-pyskyfire.regen.cross_section\" title=\"Link to this heading\">\u00b6</a></h1><h2>Classes<a class=\"headerlink\" href=\"#classes\" title=\"Link to this heading\">\u00b6</a></h2>", "a[href=\"CrossSectionRounded.html#pyskyfire.regen.cross_section.CrossSectionRounded\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.regen.cross_section.CrossSectionRounded\">\n<span class=\"property\"><span class=\"k\"><span class=\"pre\">class</span></span><span class=\"w\"> </span></span><span class=\"sig-prename descclassname\"><span class=\"pre\">pyskyfire.regen.cross_section.</span></span><span class=\"sig-name descname\"><span class=\"pre\">CrossSectionRounded</span></span><span class=\"sig-paren\">(</span><em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">n_points</span></span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"default_value\"><span class=\"pre\">16</span></span></em>, <em class=\"sig-param\"><span class=\"keyword-only-separator o\"><abbr title=\"Keyword-only parameters separator (PEP 3102)\"><span class=\"pre\">*</span></abbr></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">height_input</span></span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"default_value\"><span class=\"pre\">'full'</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">exposure</span></span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"default_value\"><span class=\"pre\">None</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">exposure_angles</span></span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"default_value\"><span class=\"pre\">None</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">enable_fin</span></span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"default_value\"><span class=\"pre\">False</span></span></em><span class=\"sig-paren\">)</span></dt><dd><p>Bases: <code class=\"xref py py-obj docutils literal notranslate\"><span class=\"pre\">ChannelSection</span></code></p><p>Two circular lobes connected by straight tangent sidewalls.</p><p>Both input routes build the same boundary: sector radius/angle/wall\nthickness, or internal floor and roof endpoint widths and height. Equal\nwidths give parallel sides; equal widths with full height equal to width\ngive a circle. A single wall thickness offsets all four surfaces.</p><p>height_input=\u201dfull\u201d measures bottom-to-top passage height; \u201cbase\u201d measures\nseparation of lobe centres. For unequal endpoint widths and full height,\nthe less steep of the two possible tangent constructions is selected.\nInvalid combinations raise rather than distorting the lobes. Angular\ninput retains its exact prescribed sidewall angle.</p></dd>", "a[href=\"CrossSectionSquared.html#pyskyfire.regen.cross_section.CrossSectionSquared\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.regen.cross_section.CrossSectionSquared\">\n<span class=\"property\"><span class=\"k\"><span class=\"pre\">class</span></span><span class=\"w\"> </span></span><span class=\"sig-prename descclassname\"><span class=\"pre\">pyskyfire.regen.cross_section.</span></span><span class=\"sig-name descname\"><span class=\"pre\">CrossSectionSquared</span></span><span class=\"sig-paren\">(</span><em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">sidewall_half_thickness</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">n_points</span></span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"default_value\"><span class=\"pre\">8</span></span></em>, <em class=\"sig-param\"><span class=\"keyword-only-separator o\"><abbr title=\"Keyword-only parameters separator (PEP 3102)\"><span class=\"pre\">*</span></abbr></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">roof_thickness</span></span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"default_value\"><span class=\"pre\">None</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">floor</span></span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"default_value\"><span class=\"pre\">'arc'</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">roof</span></span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"default_value\"><span class=\"pre\">'arc'</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">exposure</span></span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"default_value\"><span class=\"pre\">None</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">enable_fin</span></span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"default_value\"><span class=\"pre\">False</span></span></em><span class=\"sig-paren\">)</span></dt><dd><p>Bases: <code class=\"xref py py-obj docutils literal notranslate\"><span class=\"pre\">ChannelSection</span></code></p><p>Squared passages with independently straight or curved floor and roof.</p><p>sidewall_half_thickness [m] is ONE tube sidewall\u2019s normal thickness,\nequivalent to HALF the shared rib between adjacent chamber channels. A\nconstant or design-input callable is accepted. A former 1 mm full rib is\ntherefore specified as 0.5 mm here.</p><p>Floor thickness comes from SectionProfiles.t_wall. roof_thickness defaults\nto that thickness and may instead be a constant or callable. floor and roof\nindependently accept \u201carc\u201d or \u201cline\u201d. Direct width profiles use the\ndistance between internal sidewall endpoints. With sector profiles, the\nexisting constant-material-width rib construction determines those\nendpoints; choosing a line joins the same endpoints with a chord.</p></dd>", "a[href=\"#classes\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Classes<a class=\"headerlink\" href=\"#classes\" title=\"Link to this heading\">\u00b6</a></h2>"}
skip_classes = ["headerlink", "sd-stretched-link"]

window.onload = function () {
    for (const [select, tip_html] of Object.entries(selector_to_html)) {
        const links = document.querySelectorAll(` ${select}`);
        for (const link of links) {
            if (skip_classes.some(c => link.classList.contains(c))) {
                continue;
            }

            tippy(link, {
                content: tip_html,
                allowHTML: true,
                arrow: true,
                placement: 'auto-start', maxWidth: 600, interactive: false,
                onShow(instance) {MathJax.typesetPromise([instance.popper]).then(() => {});},
            });
        };
    };
    console.log("tippy tips loaded!");
};
